import React, { useEffect, useState } from "react";
import axios from "axios";
import { useParams, useNavigate } from "react-router-dom";

export default function EditDriverForm() {
  const { id } = useParams();
  const navigate = useNavigate();
  const [form, setForm] = useState({
    name: "",
    email: "",
    phone: "",
    licenseNumber: "",
    status: "active",
    isAvailable: true,
    currentOrders: 0,
  });
  const [message, setMessage] = useState("");

  useEffect(() => {
    if (!id) return;
    axios
      .get(`http://localhost:5000/api/drivers/${id}`)
      .then((res) => setForm(res.data))
      .catch(() => setMessage("❌ Failed to load driver"));
  }, [id]);

  const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const { name, value } = e.target;
    setForm((prev) => ({ ...prev, [name]: value }));
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      await axios.put(`http://localhost:5000/api/drivers/${id}`, form);
      setMessage("✅ Driver updated successfully!");
      setTimeout(() => navigate("/drivers"), 1000);
    } catch {
      setMessage("❌ Failed to update driver");
    }
  };

  return (
    <form onSubmit={handleSubmit} style={{ maxWidth: 400, margin: "auto", padding: 20 }}>
      <h2>Edit Driver</h2>
      {["name", "email", "phone", "licenseNumber"].map((field) => (
        <input
          key={field}
          name={field}
          placeholder={field}
          value={(form as any)[field]}
          onChange={handleChange}
          style={{ width: "100%", padding: 8, marginBottom: 10 }}
          required
        />
      ))}
      <button type="submit">Update</button>
      {message && <p>{message}</p>}
    </form>
  );
}
